    for item in presentations:  # 顺序校验，失败不短路
        valid, reason = self.verify_trust_presentation(
            tenant_id, item, allow_holder_bound=True
        )
        if valid:
            results.append({"valid": True})
        else:
            results.append(
                {"valid": False, "reason": reason or "验签失败"}
            )
